package com.campusevents.dao;
import com.campusevents.model.Event;import com.campusevents.util.DatabaseConnection;import java.sql.*;import java.time.*;import java.util.*;
public class EventDAO {private static final String BASE="SELECT e.event_id,e.title,e.description,c.category_name,o.name,e.event_date,e.start_time,e.end_time,e.venue,e.registration_deadline,e.capacity,e.status,(SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.event_id AND r.status='CONFIRMED'),(SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.event_id AND r.status='WAITLISTED') FROM events e JOIN categories c ON c.category_id=e.category_id JOIN organizers o ON o.organizer_id=e.organizer_id";private Event map(ResultSet r)throws SQLException{return new Event(r.getInt(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),LocalDate.parse(r.getString(6)),LocalTime.parse(r.getString(7)),LocalTime.parse(r.getString(8)),r.getString(9),LocalDate.parse(r.getString(10)),r.getInt(11),r.getString(12),r.getInt(13),r.getInt(14));}public List<Event> search(String key,String cat)throws SQLException{List<Event>a=new ArrayList<>();String k=key==null?"":key.toLowerCase();String q=BASE+" WHERE (?='' OR lower(e.title) LIKE ? OR lower(e.venue) LIKE ? OR lower(e.description) LIKE ?) AND (?='All' OR c.category_name=?) ORDER BY e.event_date";try(Connection c=DatabaseConnection.get();PreparedStatement p=c.prepareStatement(q)){p.setString(1,k);p.setString(2,"%"+k+"%");p.setString(3,"%"+k+"%");p.setString(4,"%"+k+"%");p.setString(5,cat);p.setString(6,cat);try(ResultSet r=p.executeQuery()){while(r.next())a.add(map(r));}}return a;}public Event get(int id)throws SQLException{try(Connection c=DatabaseConnection.get();PreparedStatement p=c.prepareStatement(BASE+" WHERE e.event_id=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next()?map(r):null;}}}public List<String> categories()throws SQLException{List<String>a=new ArrayList<>(List.of("All"));try(Connection c=DatabaseConnection.get();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT category_name FROM categories ORDER BY category_name")){while(r.next())a.add(r.getString(1));}return a;}public void save(int id,String title,String desc,String cat,String org,LocalDate date,LocalTime start,LocalTime end,String venue,LocalDate deadline,int cap,String status)throws SQLException{try(Connection c=DatabaseConnection.get()){int category;try(PreparedStatement p=c.prepareStatement("INSERT OR IGNORE INTO categories(category_name) VALUES(?)")){p.setString(1,cat);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("SELECT category_id FROM categories WHERE category_name=?")){p.setString(1,cat);try(ResultSet r=p.executeQuery()){r.next();category=r.getInt(1);}}String em=org.toLowerCase().replaceAll("[^a-z0-9]","")+"@organizer.local";try(PreparedStatement p=c.prepareStatement("INSERT OR IGNORE INTO organizers(name,email) VALUES(?,?)")){p.setString(1,org);p.setString(2,em);p.executeUpdate();}int organizer;try(PreparedStatement p=c.prepareStatement("SELECT organizer_id FROM organizers WHERE email=?")){p.setString(1,em);try(ResultSet r=p.executeQuery()){r.next();organizer=r.getInt(1);}}String q=id==0?"INSERT INTO events(title,description,category_id,organizer_id,event_date,start_time,end_time,venue,registration_deadline,capacity,status) VALUES(?,?,?,?,?,?,?,?,?,?,?)":"UPDATE events SET title=?,description=?,category_id=?,organizer_id=?,event_date=?,start_time=?,end_time=?,venue=?,registration_deadline=?,capacity=?,status=? WHERE event_id=?";try(PreparedStatement p=c.prepareStatement(q)){p.setString(1,title);p.setString(2,desc);p.setInt(3,category);p.setInt(4,organizer);p.setString(5,date.toString());p.setString(6,start.toString());p.setString(7,end.toString());p.setString(8,venue);p.setString(9,deadline.toString());p.setInt(10,cap);p.setString(11,status);if(id!=0)p.setInt(12,id);p.executeUpdate();}}}public void cancel(int id)throws SQLException{try(Connection c=DatabaseConnection.get();PreparedStatement p=c.prepareStatement("UPDATE events SET status='CANCELLED' WHERE event_id=?")){p.setInt(1,id);p.executeUpdate();}}
}
